   1  import {
   2    PublicKey,
   3    SystemProgram,
   4    TransactionInstruction,
   5    LAMPORTS_PER_SOL,
   6  } from "@solana/web3.js";
   7  import {
   8    PROTOCOL_FEE_BPS,
   9    PROXIMA_FEE_BPS,
  10    DEFAULT_PLATFORM_FEE_VAULT,
  11  } from "./constants";
  12  
  13  export interface FeeCalculation {
  14    grossLamports: bigint;
  15    feeLamports: bigint;
  16    netLamports: bigint;
  17    grossSol: number;
  18    feeSol: number;
  19    netSol: number;
  20    proximaTaxSol: number;
  21    userSavingsSol: number;
  22  }
  23  
  24  /**
  25   * Calculates SCRAMJET 3.5% protocol fee with lamport precision
  26   * and benchmarks user savings vs Proxima's 5.0% fee.
  27   */
  28  export function calculateProtocolFee(
  29    amountLamports: bigint,
  30    feeBps: number = PROTOCOL_FEE_BPS
  31  ): FeeCalculation {
  32    const feeLamports = (amountLamports * BigInt(feeBps)) / BigInt(10000);
  33    const netLamports = amountLamports - feeLamports;
  34  
  35    const proximaFeeLamports =
  36      (amountLamports * BigInt(PROXIMA_FEE_BPS)) / BigInt(10000);
  37    const userSavingsLamports = proximaFeeLamports - feeLamports;
  38  
  39    return {
  40      grossLamports: amountLamports,
  41      feeLamports,
  42      netLamports,
  43      grossSol: Number(amountLamports) / LAMPORTS_PER_SOL,
  44      feeSol: Number(feeLamports) / LAMPORTS_PER_SOL,
  45      netSol: Number(netLamports) / LAMPORTS_PER_SOL,
  46      proximaTaxSol: Number(proximaFeeLamports) / LAMPORTS_PER_SOL,
  47      userSavingsSol: Number(userSavingsLamports) / LAMPORTS_PER_SOL,
  48    };
  49  }
  50  
  51  /**
  52   * Builds the platform fee deduction instruction (SystemProgram.transfer)
  53   */
  54  export function buildProtocolFeeInstruction(
  55    payer: PublicKey,
  56    feeLamports: bigint,
  57    feeRecipient: PublicKey = DEFAULT_PLATFORM_FEE_VAULT
  58  ): TransactionInstruction {
  59    if (feeLamports <= BigInt(0)) {
  60      throw new Error("Protocol fee lamports must be greater than zero");
  61    }
  62  
  63    return SystemProgram.transfer({
  64      fromPubkey: payer,
  65      toPubkey: feeRecipient,
  66      lamports: feeLamports,
  67    });
  68  }
