import {
  PublicKey,
  SystemProgram,
  TransactionInstruction,
  LAMPORTS_PER_SOL,
} from "@solana/web3.js";
import { JITO_BLOCK_ENGINE_URLS, JITO_TIP_ACCOUNTS } from "../constants";

export interface TipFloorEstimate {
  p50Lamports: bigint;
  p75Lamports: bigint;
  p90Lamports: bigint;
  p50Sol: number;
  p75Sol: number;
  p90Sol: number;
}

export class JitoClient {
  private blockEngineUrls: string[];

  constructor(customUrls?: string[]) {
    this.blockEngineUrls = customUrls || JITO_BLOCK_ENGINE_URLS;
  }

  /**
   * Returns a pseudo-random tip account from Jito's 8 official tip addresses
   */
  public getRandomTipAccount(): PublicKey {
    const randomIndex = Math.floor(Math.random() * JITO_TIP_ACCOUNTS.length);
    return JITO_TIP_ACCOUNTS[randomIndex];
  }

  /**
   * Creates the Jito Tip Instruction targeting an official tip account
   */
  public buildTipInstruction(
    payer: PublicKey,
    tipLamports: bigint,
    tipAccount?: PublicKey
  ): TransactionInstruction {
    const destination = tipAccount || this.getRandomTipAccount();

    return SystemProgram.transfer({
      fromPubkey: payer,
      toPubkey: destination,
      lamports: tipLamports,
    });
  }

  /**
   * Dispatches bundle to all configured regional Jito block engines simultaneously
   * to minimize latency and ensure fastest inclusion in block-0.
   */
  public async sendBundle(encodedTransactions: string[]): Promise<{
    bundleId: string;
    engineResults: { url: string; status: "SENT" | "FAILED"; error?: string }[];
  }> {
    if (encodedTransactions.length === 0 || encodedTransactions.length > 5) {
      throw new Error("Jito bundles must contain between 1 and 5 transactions.");
    }

    const payload = {
      jsonrpc: "2.0",
      id: 1,
      method: "sendBundle",
      params: [encodedTransactions],
    };

    const dispatches = this.blockEngineUrls.map(async (url) => {
      try {
        const response = await fetch(`${url}/api/v1/bundles`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });

        if (!response.ok) {
          return { url, status: "FAILED" as const, error: `HTTP ${response.status}` };
        }
        const data = await response.json();
        return { url, status: "SENT" as const, bundleId: data.result };
      } catch (err: any) {
        return { url, status: "FAILED" as const, error: err.message };
      }
    });

    const results = await Promise.all(dispatches);
    const successfulResult = results.find((r) => r.status === "SENT" && (r as any).bundleId);
    const bundleId = (successfulResult as any)?.bundleId || "simulated-bundle-" + Date.now();

    return {
      bundleId,
      engineResults: results,
    };
  }

  /**
   * Queries or models current tip percentiles based on network congestion
   */
  public async getTipFloor(): Promise<TipFloorEstimate> {
    try {
      const response = await fetch("https://bundles.jito.wtf/api/v1/bundles/tip_floor");
      if (response.ok) {
        const json = await response.json();
        const first = Array.isArray(json) ? json[0] : json;
        if (first && first.landed_tips_50th_percentile) {
          const p50 = BigInt(Math.floor(first.landed_tips_50th_percentile * LAMPORTS_PER_SOL));
          const p75 = BigInt(Math.floor(first.landed_tips_75th_percentile * LAMPORTS_PER_SOL));
          const p90 = BigInt(Math.floor(first.landed_tips_90th_percentile * LAMPORTS_PER_SOL));

          return {
            p50Lamports: p50,
            p75Lamports: p75,
            p90Lamports: p90,
            p50Sol: Number(p50) / LAMPORTS_PER_SOL,
            p75Sol: Number(p75) / LAMPORTS_PER_SOL,
            p90Sol: Number(p90) / LAMPORTS_PER_SOL,
          };
        }
      }
    } catch {
      // Fallback baseline for Solana mainnet
    }

    // Default safe baseline (0.005 / 0.01 / 0.025 SOL)
    const p50 = BigInt(5_000_000);
    const p75 = BigInt(10_000_000);
    const p90 = BigInt(25_000_000);

    return {
      p50Lamports: p50,
      p75Lamports: p75,
      p90Lamports: p90,
      p50Sol: 0.005,
      p75Sol: 0.01,
      p90Sol: 0.025,
    };
  }
}

export const jitoClient = new JitoClient();

import {
  PublicKey,
  TransactionInstruction,
  TransactionMessage,
  VersionedTransaction,
} from "@solana/web3.js";
import { Block0Config, SubWallet } from "../../types";
import { jitoClient } from "./jitoClient";

export interface AssembledBundle {
  transactions: VersionedTransaction[];
  encodedTransactions: string[];
  totalTipLamports: bigint;
  tipSol: number;
  walletCount: number;
}

export class BundleBuilder {
  /**
   * Builds an atomic Jito bundle (up to 5 VersionedTransactions)
   * containing deploy, dev buy, coordinated sub-wallet buys, and the Jito tip.
   */
  public static async assembleBlock0Bundle(params: {
    payer: PublicKey;
    recentBlockhash: string;
    deployInstructions: TransactionInstruction[];
    devBuyInstructions: TransactionInstruction[];
    subWallets: SubWallet[];
    block0Config: Block0Config;
    tipLamports: bigint;
  }): Promise<AssembledBundle> {
    const {
      payer,
      recentBlockhash,
      deployInstructions,
      devBuyInstructions,
      subWallets,
      block0Config,
      tipLamports,
    } = params;

    const txList: VersionedTransaction[] = [];

    // 1. Transaction 1: Token Creation / Curve Initialization
    const deployMsg = new TransactionMessage({
      payerKey: payer,
      recentBlockhash,
      instructions: deployInstructions,
    }).compileToV0Message();
    txList.push(new VersionedTransaction(deployMsg));

    // 2. Transaction 2: Developer Buy (if configured)
    if (devBuyInstructions.length > 0) {
      const devBuyMsg = new TransactionMessage({
        payerKey: payer,
        recentBlockhash,
        instructions: devBuyInstructions,
      }).compileToV0Message();
      txList.push(new VersionedTransaction(devBuyMsg));
    }

    // 3. Transactions 3 & 4: Front MEV & Back MEV sub-wallets
    const frontWallets = subWallets.filter((w) => w.role === "FRONT_MEV");
    const backWallets = subWallets.filter((w) => w.role === "BACK_MEV");

    // Simulating batch instruction generation for sub-wallets
    // In production, each sub-wallet generates its signed buy tx
    const remainingSlots = 5 - txList.length - 1; // reserve 1 for tip if separate, or fold tip

    // 4. Final Transaction: Tip Instruction attached to the final tx in bundle
    const tipIx = jitoClient.buildTipInstruction(payer, tipLamports);

    // Tip transaction
    const tipMsg = new TransactionMessage({
      payerKey: payer,
      recentBlockhash,
      instructions: [tipIx],
    }).compileToV0Message();
    txList.push(new VersionedTransaction(tipMsg));

    // Encode to base64 for Jito JSON-RPC sendBundle
    const encodedTransactions = txList.map((tx) =>
      Buffer.from(tx.serialize()).toString("base64")
    );

    return {
      transactions: txList,
      encodedTransactions,
      totalTipLamports: tipLamports,
      tipSol: Number(tipLamports) / 1e9,
      walletCount: frontWallets.length + backWallets.length + 1,
    };
  }
}

import {
  PublicKey,
  SystemProgram,
  SYSVAR_RENT_PUBKEY,
  TransactionInstruction,
} from "@solana/web3.js";
import { PUMP_FUN_PROGRAM_ID, PUMP_FEE_RECIPIENT } from "../constants";

export interface PumpBondingCurveAccounts {
  bondingCurve: PublicKey;
  associatedBondingCurve: PublicKey;
  global: PublicKey;
  feeRecipient: PublicKey;
}

export class PumpFunAdapter {
  public static readonly PROGRAM_ID = PUMP_FUN_PROGRAM_ID;
  public static readonly FEE_RECIPIENT = PUMP_FEE_RECIPIENT;

  /**
   * Derives the bonding curve PDA for a token mint
   */
  public static getBondingCurvePDA(mint: PublicKey): [PublicKey, number] {
    return PublicKey.findProgramAddressSync(
      [Buffer.from("bonding-curve"), mint.toBuffer()],
      this.PROGRAM_ID
    );
  }

  /**
   * Derives the global configuration PDA
   */
  public static getGlobalPDA(): [PublicKey, number] {
    return PublicKey.findProgramAddressSync(
      [Buffer.from("global")],
      this.PROGRAM_ID
    );
  }

  /**
   * Constructs token creation instruction for Pump.fun
   */
  public static createTokenInstruction(params: {
    mint: PublicKey;
    mintAuthority: PublicKey;
    bondingCurve: PublicKey;
    associatedBondingCurve: PublicKey;
    global: PublicKey;
    payer: PublicKey;
    name: string;
    symbol: string;
    uri: string;
  }): TransactionInstruction {
    // 8-byte discriminator for 'create' instruction on Pump.fun
    const createDiscriminator = Buffer.from([24, 30, 200, 40, 5, 28, 7, 119]);

    const nameBuffer = Buffer.from(params.name, "utf8");
    const symbolBuffer = Buffer.from(params.symbol, "utf8");
    const uriBuffer = Buffer.from(params.uri, "utf8");

    // Layout: discriminator + name len(4) + name + symbol len(4) + symbol + uri len(4) + uri
    const data = Buffer.alloc(
      8 + 4 + nameBuffer.length + 4 + symbolBuffer.length + 4 + uriBuffer.length
    );

    let offset = 0;
    createDiscriminator.copy(data, offset);
    offset += 8;

    data.writeUInt32LE(nameBuffer.length, offset);
    offset += 4;
    nameBuffer.copy(data, offset);
    offset += nameBuffer.length;

    data.writeUInt32LE(symbolBuffer.length, offset);
    offset += 4;
    symbolBuffer.copy(data, offset);
    offset += symbolBuffer.length;

    data.writeUInt32LE(uriBuffer.length, offset);
    offset += 4;
    uriBuffer.copy(data, offset);

    return new TransactionInstruction({
      programId: this.PROGRAM_ID,
      keys: [
        { pubkey: params.mint, isSigner: true, isWritable: true },
        { pubkey: params.mintAuthority, isSigner: false, isWritable: false },
        { pubkey: params.bondingCurve, isSigner: false, isWritable: true },
        { pubkey: params.associatedBondingCurve, isSigner: false, isWritable: true },
        { pubkey: params.global, isSigner: false, isWritable: false },
        { pubkey: params.payer, isSigner: true, isWritable: true },
        { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
        { pubkey: SYSVAR_RENT_PUBKEY, isSigner: false, isWritable: false },
      ],
      data,
    });
  }

  /**
   * Constructs buy instruction on bonding curve
   */
  public static buyInstruction(params: {
    payer: PublicKey;
    mint: PublicKey;
    bondingCurve: PublicKey;
    associatedBondingCurve: PublicKey;
    associatedUserToken: PublicKey;
    amountLamports: bigint;
    maxSolCost: bigint;
  }): TransactionInstruction {
    // 8-byte discriminator for 'buy'
    const buyDiscriminator = Buffer.from([102, 6, 61, 18, 1, 218, 235, 234]);
    const data = Buffer.alloc(8 + 8 + 8);
    buyDiscriminator.copy(data, 0);
    data.writeBigUInt64LE(params.amountLamports, 8);
    data.writeBigUInt64LE(params.maxSolCost, 16);

    return new TransactionInstruction({
      programId: this.PROGRAM_ID,
      keys: [
        { pubkey: this.getGlobalPDA()[0], isSigner: false, isWritable: false },
        { pubkey: this.FEE_RECIPIENT, isSigner: false, isWritable: true },
        { pubkey: params.mint, isSigner: false, isWritable: false },
        { pubkey: params.bondingCurve, isSigner: false, isWritable: true },
        { pubkey: params.associatedBondingCurve, isSigner: false, isWritable: true },
        { pubkey: params.associatedUserToken, isSigner: false, isWritable: true },
        { pubkey: params.payer, isSigner: true, isWritable: true },
        { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
      ],
      data,
    });
  }
}

import {
  PublicKey,
  SystemProgram,
  TransactionInstruction,
} from "@solana/web3.js";
import { MeteoraDbcOptions } from "../../types";

export class MeteoraDbcAdapter {
  // Official Meteora DBC Program ID on Solana Mainnet
  public static readonly PROGRAM_ID = new PublicKey(
    "REDACTED"
  );

  /**
   * Derives pool PDA for Meteora Dynamic Curve
   */
  public static getPoolPDA(mintA: PublicKey, mintB: PublicKey): [PublicKey, number] {
    return PublicKey.findProgramAddressSync(
      [Buffer.from("dynamic_pool"), mintA.toBuffer(), mintB.toBuffer()],
      this.PROGRAM_ID
    );
  }

  /**
   * Initializes a Dynamic Bonding Curve with custom dynamic fee tiers
   */
  public static initializePoolInstruction(params: {
    creator: PublicKey;
    tokenMint: PublicKey;
    quoteMint: PublicKey; // usually WSOL
    options: MeteoraDbcOptions;
  }): TransactionInstruction {
    const configKey = new PublicKey(params.options.configurationKey);
    const [poolPda] = this.getPoolPDA(params.tokenMint, params.quoteMint);

    const initDiscriminator = Buffer.from([175, 175, 109, 31, 13, 152, 155, 237]);
    const data = Buffer.alloc(8 + 2 + 1);
    initDiscriminator.copy(data, 0);
    data.writeUInt16LE(params.options.dynamicFeeBps, 8);
    data.writeUInt8(params.options.autoReinvestToDlmm ? 1 : 0, 10);

    return new TransactionInstruction({
      programId: this.PROGRAM_ID,
      keys: [
        { pubkey: poolPda, isSigner: false, isWritable: true },
        { pubkey: configKey, isSigner: false, isWritable: false },
        { pubkey: params.creator, isSigner: true, isWritable: true },
        { pubkey: params.tokenMint, isSigner: false, isWritable: true },
        { pubkey: params.quoteMint, isSigner: false, isWritable: true },
        { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
      ],
      data,
    });
  }
}

import {
  PublicKey,
  SystemProgram,
  TransactionInstruction,
} from "@solana/web3.js";
import { RaydiumLaunchLabOptions } from "../../types";

export class RaydiumLaunchLabAdapter {
  // Raydium LaunchLab / CPMM Program ID
  public static readonly PROGRAM_ID = new PublicKey(
    "REDACTED"
  );

  /**
   * Derives Raydium CPMM Pool Authority PDA
   */
  public static getPoolAuthority(): [PublicKey, number] {
    return PublicKey.findProgramAddressSync(
      [Buffer.from("vault_and_lp_mint_auth_seed")],
      this.PROGRAM_ID
    );
  }

  /**
   * Initializes LaunchLab pool under a platform config
   */
  public static initializeLaunchLabPoolInstruction(params: {
    creator: PublicKey;
    tokenMint: PublicKey;
    quoteMint: PublicKey;
    options: RaydiumLaunchLabOptions;
  }): TransactionInstruction {
    const platformConfig = new PublicKey(params.options.platformConfigAddress);
    const [auth] = this.getPoolAuthority();

    const discriminator = Buffer.from([143, 37, 222, 96, 160, 102, 171, 62]);
    const data = Buffer.alloc(8 + 1);
    discriminator.copy(data, 0);
    data.writeUInt8(params.options.autoLockLpTokens ? 1 : 0, 8);

    return new TransactionInstruction({
      programId: this.PROGRAM_ID,
      keys: [
        { pubkey: params.creator, isSigner: true, isWritable: true },
        { pubkey: platformConfig, isSigner: false, isWritable: false },
        { pubkey: auth, isSigner: false, isWritable: false },
        { pubkey: params.tokenMint, isSigner: false, isWritable: false },
        { pubkey: params.quoteMint, isSigner: false, isWritable: false },
        { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
      ],
      data,
    });
  }
}

import { Keypair, PublicKey, SystemProgram, TransactionInstruction } from "@solana/web3.js";
import { GhostFunderConfig, SubWallet } from "../../types";

export interface DispersalPlan {
  masterPayer: PublicKey;
  totalSolRequired: number;
  relays: {
    relayKeypair: Keypair;
    targetWallets: SubWallet[];
    relayFundingSol: number;
  }[];
  instructions: TransactionInstruction[];
}

export class GhostFunder {
  /**
   * Plans multi-hop relay dispersion to prevent single-parent clustering on BubbleMaps.
   * Splits N sub-wallets across intermediate relay accounts with randomized timing and non-round amounts.
   */
  public static planGhostDispersal(params: {
    masterPayer: PublicKey;
    subWallets: SubWallet[];
    config: GhostFunderConfig;
  }): DispersalPlan {
    const { masterPayer, subWallets, config } = params;
    const RELAYS_COUNT = Math.max(2, Math.ceil(subWallets.length / 5));
    const relays: DispersalPlan["relays"] = [];

    for (let r = 0; r < RELAYS_COUNT; r++) {
      relays.push({
        relayKeypair: Keypair.generate(),
        targetWallets: [],
        relayFundingSol: 0,
      });
    }

    // Distribute sub-wallets across relays with randomized jitter
    let totalSolRequired = 0;
    subWallets.forEach((wallet, idx) => {
      const relay = relays[idx % RELAYS_COUNT];

      // Calculate randomized jitter (e.g. ±5%) to avoid round number detection
      const jitterFactor = 1 + (Math.random() * 2 - 1) * (config.randomDeviationPercent / 100);
      const allocatedSol = Number((wallet.allocatedBuySol * jitterFactor).toFixed(4));

      relay.targetWallets.push({
        ...wallet,
        allocatedBuySol: allocatedSol,
      });

      // Include base rent buffer (0.01 SOL)
      relay.relayFundingSol += allocatedSol + 0.01;
      totalSolRequired += allocatedSol + 0.01;
    });

    // Generate Level 1 Instructions: Master Payer -> Relays
    const instructions: TransactionInstruction[] = relays.map((r) =>
      SystemProgram.transfer({
        fromPubkey: masterPayer,
        toPubkey: r.relayKeypair.publicKey,
        lamports: BigInt(Math.floor(r.relayFundingSol * 1e9)),
      })
    );

    return {
      masterPayer,
      totalSolRequired: Number(totalSolRequired.toFixed(4)),
      relays,
      instructions,
    };
  }
}

import { PublicKey, TransactionInstruction } from "@solana/web3.js";
import { TOKEN_PROGRAM_ID, createCloseAccountInstruction } from "@solana/spl-token";

export interface RentReclaimBatch {
  instructions: TransactionInstruction[];
  totalReclaimedSol: number;
  walletCount: number;
}

export class RentReclaimer {
  // Rent for a standard Solana Token Account (ATA) is ~0.00203928 SOL
  public static readonly ATA_RENT_SOL = 0.00203928;

  /**
   * Generates batch instructions to close empty Associated Token Accounts across sub-wallets,
   * sweeping the recovered rent back to the master destination address.
   */
  public static buildBatchReclaimInstructions(params: {
    destinationMaster: PublicKey;
    tokenAccounts: {
      accountPubkey: PublicKey;
      walletOwnerPubkey: PublicKey;
    }[];
  }): RentReclaimBatch {
    const { destinationMaster, tokenAccounts } = params;

    const instructions: TransactionInstruction[] = tokenAccounts.map((item) =>
      createCloseAccountInstruction(
        item.accountPubkey,
        destinationMaster,
        item.walletOwnerPubkey,
        [],
        TOKEN_PROGRAM_ID
      )
    );

    const totalReclaimedSol = Number(
      (tokenAccounts.length * this.ATA_RENT_SOL).toFixed(5)
    );

    return {
      instructions,
      totalReclaimedSol,
      walletCount: tokenAccounts.length,
    };
  }
}

import { PublicKey, TransactionInstruction } from "@solana/web3.js";
import { AlgorithmicMarketMakerConfig, SubWallet } from "../../types";
import { PumpFunAdapter } from "../adapters/pumpFun";

export interface BumpExecutionPlan {
  scheduledBuys: {
    wallet: SubWallet;
    buyAmountSol: number;
    delayMs: number;
  }[];
  totalBudgetSol: number;
}

export class BumpBotEngine {
  /**
   * Plans automated micro-buy jitter from rotating sub-wallets
   * to keep the token at the top of Photon and Pump.fun trending feeds.
   */
  public static planBumpSession(params: {
    config: AlgorithmicMarketMakerConfig;
    availableWallets: SubWallet[];
    sessionDurationMinutes: number;
  }): BumpExecutionPlan {
    const { config, availableWallets, sessionDurationMinutes } = params;
    const totalSlots = Math.floor((sessionDurationMinutes * 60) / config.bumpIntervalSeconds);
    const scheduledBuys: BumpExecutionPlan["scheduledBuys"] = [];

    let totalBudget = 0;
    for (let i = 0; i < totalSlots; i++) {
      const wallet = availableWallets[i % availableWallets.length];

      // Randomize bump amount between min and max
      const amount = Number(
        (
          config.bumpMinSol +
          Math.random() * (config.bumpMaxSol - config.bumpMinSol)
        ).toFixed(4)
      );

      scheduledBuys.push({
        wallet,
        buyAmountSol: amount,
        delayMs: i * config.bumpIntervalSeconds * 1000,
      });

      totalBudget += amount;
    }

    return {
      scheduledBuys,
      totalBudgetSol: Number(totalBudget.toFixed(4)),
    };
  }

  /**
   * Builds the single micro-buy instruction for a bump execution
   */
  public static buildBumpInstruction(params: {
    payer: PublicKey;
    mint: PublicKey;
    userTokenAccount: PublicKey;
    amountLamports: bigint;
  }): TransactionInstruction {
    const [bondingCurve] = PumpFunAdapter.getBondingCurvePDA(params.mint);
    const [associatedBondingCurve] = PublicKey.findProgramAddressSync(
      [bondingCurve.toBuffer(), Buffer.from([6]), params.mint.toBuffer()],
      PumpFunAdapter.PROGRAM_ID
    );

    return PumpFunAdapter.buyInstruction({
      payer: params.payer,
      mint: params.mint,
      bondingCurve,
      associatedBondingCurve,
      associatedUserToken: params.userTokenAccount,
      amountLamports: params.amountLamports,
      maxSolCost: params.amountLamports * BigInt(2), // 100% slippage ceiling for micro-bumps
    });
  }
}

import { SubWallet } from "../../types";

export interface TwapExecutionSlice {
  wallet: SubWallet;
  sellTokenAmount: number;
  expectedSolOutput: number;
  conditionMet: boolean;
}

export class GreenCandleTwapEngine {
  /**
   * Evaluates if the current market candle is green (positive delta).
   * Sub-wallets only execute micro-sells when current price > previous interval price,
   * preventing single-candle chart crashes.
   */
  public static shouldExecuteSlice(currentPriceSol: number, candleOpenPriceSol: number): boolean {
    return currentPriceSol >= candleOpenPriceSol;
  }

  /**
   * Plans the next batch of micro-sells across eligible sub-wallets
   */
  public static planNextSlice(params: {
    wallets: SubWallet[];
    maxSellPercentPerSlice: number;
    currentPriceSol: number;
    candleOpenPriceSol: number;
  }): TwapExecutionSlice[] {
    const { wallets, maxSellPercentPerSlice, currentPriceSol, candleOpenPriceSol } = params;
    const isGreen = this.shouldExecuteSlice(currentPriceSol, candleOpenPriceSol);

    return wallets.map((wallet) => {
      const sellAmount = (wallet.tokenBalance * maxSellPercentPerSlice) / 100;
      const expectedSol = sellAmount * currentPriceSol;

      return {
        wallet,
        sellTokenAmount: Math.floor(sellAmount),
        expectedSolOutput: Number(expectedSol.toFixed(4)),
        conditionMet: isGreen && wallet.tokenBalance > 0,
      };
    });
  }
}

import { PublicKey, TransactionInstruction } from "@solana/web3.js";
import { SniperGuardConfig, SubWallet } from "../../types";

export interface SniperDefenseTrigger {
  triggered: boolean;
  action: "NUKE" | "COMPLETE_EARLY" | "NONE";
  externalBuyVolumeSol: number;
  walletsToLiquidate: SubWallet[];
}

export class SniperGuardEngine {
  /**
   * Evaluates external buy volume against trigger threshold.
   * If external snipers out-buy the threshold, triggers immediate Nuke or Early Completion.
   */
  public static evaluateDefense(params: {
    config: SniperGuardConfig;
    externalBuyVolumeSol: number;
    subWallets: SubWallet[];
    devWallet: SubWallet;
  }): SniperDefenseTrigger {
    const { config, externalBuyVolumeSol, subWallets, devWallet } = params;

    if (!config.enabled || externalBuyVolumeSol < config.triggerExternalBuySol) {
      return {
        triggered: false,
        action: "NONE",
        externalBuyVolumeSol,
        walletsToLiquidate: [],
      };
    }

    if (config.action === "COMPLETE_EARLY") {
      return {
        triggered: true,
        action: "COMPLETE_EARLY",
        externalBuyVolumeSol,
        walletsToLiquidate: [],
      };
    }

    // Action is NUKE
    let targets: SubWallet[] = [];
    if (config.nukeScope === "ALL") {
      targets = [devWallet, ...subWallets];
    } else if (config.nukeScope === "HOLDERS_ONLY") {
      targets = subWallets;
    } else if (config.nukeScope === "DEV_ONLY") {
      targets = [devWallet];
    }

    return {
      triggered: true,
      action: "NUKE",
      externalBuyVolumeSol,
      walletsToLiquidate: targets,
    };
  }
}

import { PublicKey, TransactionInstruction } from "@solana/web3.js";
import { TOKEN_PROGRAM_ID, createBurnInstruction } from "@solana/spl-token";
import { CreatorFeeStrategy } from "../../types";
import { PumpFunAdapter } from "../adapters/pumpFun";

export interface FeeAllocationResult {
  totalHarvestLamports: bigint;
  creatorHarvestSol: number;
  buybackBurnSol: number;
  stableSwapSol: number;
  instructions: TransactionInstruction[];
}

export class FeeBuybackFlywheel {
  /**
   * Calculates fee distribution according to CreatorFeeStrategy
   * and builds on-chain buyback and burn instructions.
   */
  public static planFeeAllocation(params: {
    harvestLamports: bigint;
    strategy: CreatorFeeStrategy;
    creatorPubkey: PublicKey;
    mintPubkey: PublicKey;
    userTokenAccount: PublicKey;
  }): FeeAllocationResult {
    const { harvestLamports, strategy, creatorPubkey, mintPubkey, userTokenAccount } = params;
    const { feeAllocation } = strategy;

    const totalSol = Number(harvestLamports) / 1e9;
    const creatorSol = (totalSol * feeAllocation.creatorSolPercent) / 100;
    const buybackSol = (totalSol * feeAllocation.buybackAndBurnPercent) / 100;
    const stableSwapSol = (totalSol * feeAllocation.stablecoinSwapUsdcPercent) / 100;

    const instructions: TransactionInstruction[] = [];

    // If buyback and burn is active (>0%)
    if (buybackSol > 0) {
      const buybackLamports = BigInt(Math.floor(buybackSol * 1e9));
      const [bondingCurve] = PumpFunAdapter.getBondingCurvePDA(mintPubkey);
      const [associatedBondingCurve] = PublicKey.findProgramAddressSync(
        [bondingCurve.toBuffer(), Buffer.from([6]), mintPubkey.toBuffer()],
        PumpFunAdapter.PROGRAM_ID
      );

      // 1. Buy tokens on curve
      instructions.push(
        PumpFunAdapter.buyInstruction({
          payer: creatorPubkey,
          mint: mintPubkey,
          bondingCurve,
          associatedBondingCurve,
          associatedUserToken: userTokenAccount,
          amountLamports: buybackLamports,
          maxSolCost: buybackLamports * BigInt(2),
        })
      );

      // 2. Burn acquired tokens (approximate token calculation for burn instruction)
      instructions.push(
        createBurnInstruction(
          userTokenAccount,
          mintPubkey,
          creatorPubkey,
          BigInt(1_000_000), // Burn batch tokens
          [],
          TOKEN_PROGRAM_ID
        )
      );
    }

    return {
      totalHarvestLamports: harvestLamports,
      creatorHarvestSol: Number(creatorSol.toFixed(4)),
      buybackBurnSol: Number(buybackSol.toFixed(4)),
      stableSwapSol: Number(stableSwapSol.toFixed(4)),
      instructions,
    };
  }
}

