import {
  Connection,
  PublicKey,
  LAMPORTS_PER_SOL,
  Commitment,
} from "@solana/web3.js";

export const DEFAULT_HELIUS_RPC =
  process.env.NEXT_PUBLIC_SOLANA_RPC_URL ||
  "https://mainnet.helius-rpc.com/?api-key=REDACTED;

export const DEFAULT_HELIUS_WS =
  process.env.NEXT_PUBLIC_SOLANA_WS_URL ||
  "wss://mainnet.helius-rpc.com/?api-key=REDACTED;

export class SolanaConnectionManager {
  private static instance: Connection | null = null;

  public static getConnection(commitment: Commitment = "confirmed"): Connection {
    if (!this.instance) {
      this.instance = new Connection(DEFAULT_HELIUS_RPC, {
        commitment,
        wsEndpoint: DEFAULT_HELIUS_WS,
      });
    }
    return this.instance;
  }

  /**
   * Fetches real-time SOL balance for any public key
   */
  public static async getSolBalance(pubkey: PublicKey | string): Promise<number> {
    const pk = typeof pubkey === "string" ? new PublicKey(pubkey) : pubkey;
    const connection = this.getConnection();
    const lamports = await connection.getBalance(pk);
    return lamports / LAMPORTS_PER_SOL;
  }

  /**
   * Fetches SPL token balance for an Associated Token Account (ATA)
   */
  public static async getTokenBalance(ataPubkey: PublicKey | string): Promise<number> {
    const pk = typeof ataPubkey === "string" ? new PublicKey(ataPubkey) : ataPubkey;
    const connection = this.getConnection();
    try {
      const resp = await connection.getTokenAccountBalance(pk);
      return resp.value.uiAmount || 0;
    } catch {
      return 0;
    }
  }

  /**
   * Fetches latest blockhash for transaction compilation
   */
  public static async getLatestBlockhash(): Promise<{
    blockhash: string;
    lastValidBlockHeight: number;
  }> {
    const connection = this.getConnection();
    return connection.getLatestBlockhash("confirmed");
  }

  /**
   * Monitors transaction signature until confirmed or finalized
   */
  public static async monitorConfirmation(
    signature: string,
    timeoutMs: number = 30000
  ): Promise<boolean> {
    const connection = this.getConnection();
    const startTime = Date.now();

    while (Date.now() - startTime < timeoutMs) {
      const status = await connection.getSignatureStatus(signature);
      if (
        status.value?.confirmationStatus === "confirmed" ||
        status.value?.confirmationStatus === "finalized"
      ) {
        return !status.value.err;
      }
      await new Promise((res) => setTimeout(res, 1000));
    }
    return false;
  }

  /**
   * Subscribes to real-time slot ticker updates via WebSocket
   */
  public static subscribeSlot(onSlot: (slot: number) => void): number {
    const connection = this.getConnection();
    return connection.onSlotChange((slotInfo) => {
      onSlot(slotInfo.slot);
    });
  }

  /**
   * Unsubscribes from slot ticker
   */
  public static async unsubscribeSlot(subscriptionId: number): Promise<void> {
    const connection = this.getConnection();
    await connection.removeSlotChangeListener(subscriptionId);
  }
}

export const solanaConnection = SolanaConnectionManager.getConnection();

