import { PublicKey } from "@solana/web3.js";
import {
  LaunchConfig,
  SubWallet,
  BlockchainNetwork,
  SolanaLaunchpad,
  LaunchMode,
  BuildPreset,
} from "../../types";
import { SolanaConnectionManager } from "../solana/connection";

export interface LaunchStoreState {
  connectedWallet: PublicKey | null;
  walletBalanceSol: number;
  currentSlot: number;
  isSlotSubscribed: boolean;
  reclaimedRentSol: number;

  activeLaunchConfig: LaunchConfig;
  subWallets: SubWallet[];

  activeAutomations: {
    bumpBot: boolean;
    greenTwap: boolean;
    sniperGuard: boolean;
  };

  // Actions
  setConnectedWallet: (wallet: PublicKey | null) => void;
  updateLaunchConfig: (partial: Partial<LaunchConfig>) => void;
  setSubWallets: (wallets: SubWallet[]) => void;
  updateSubWallet: (id: string, partial: Partial<SubWallet>) => void;
  setCurrentSlot: (slot: number) => void;
  initSlotSubscription: () => () => void;
  toggleAutomation: (
    key: "bumpBot" | "greenTwap" | "sniperGuard",
    forceVal?: boolean
  ) => void;
  addReclaimedRent: (sol: number) => void;
  refreshBalances: () => Promise<void>;
}

const DEFAULT_LAUNCH_CONFIG: LaunchConfig = {
  tokenName: "SCRAM",
  tokenSymbol: "SCRAM",
  tokenDescription: "SCRAMJET Protocol Utility Token - Powering hypersonic launches on Solana.",
  imageUrl: "https://scramjet.tools/logo.png",
  network: "SOLANA",
  launchpad: "METEORA_DBC",
  meteoraDbcOptions: {
    configurationKey: "REDACTED",
    dynamicFeeBps: 250,
    autoReinvestToDlmm: true,
  },
  launchMode: "BLOCK_0",
  block0Config: {
    preset: "CLEAN_BUILD",
    frontMevCount: 2,
    backMevCount: 4,
    backMevTuning: 40,
    tempHolderCount: 0,
    holderCount: 24,
    frontToBackDelayMs: 400,
    mevToTempDelayMs: 800,
    holderBuyDelaySeconds: 2,
    enableDynamicJitoTip: true,
    jitoTipPercentile: "P75",
    customJitoTipSol: 0.015,
  },
  sniperGuard: {
    enabled: true,
    triggerExternalBuySol: 5.0,
    action: "NUKE",
    nukeScope: "HOLDERS_ONLY",
  },
  ghostFunder: {
    fundingMode: "RELAY_MERKLE_TREE",
    fundingGapSeconds: 1800, // 30m
    randomDeviationPercent: 5,
  },
  marketMaker: {
    enableBumpBot: false,
    bumpIntervalSeconds: 15,
    bumpMinSol: 0.05,
    bumpMaxSol: 0.2,
    enableGreenCandleTwap: false,
    twapMaxSellPercentPerSlice: 10,
    targetTrendingBoard: "PHOTON",
  },
  feeStrategy: {
    harvestIntervalMinutes: 10,
    autoHarvest: true,
    feeAllocation: {
      creatorSolPercent: 50,
      buybackAndBurnPercent: 50,
      stablecoinSwapUsdcPercent: 0,
    },
  },
  devBuySol: 2.5,
  subWallets: [],
};

export const useLaunchStore = create<LaunchStoreState>((set, get) => ({
  connectedWallet: null,
  walletBalanceSol: 0,
  currentSlot: 464750662,
  isSlotSubscribed: false,
  reclaimedRentSol: 0.1632,

  activeLaunchConfig: DEFAULT_LAUNCH_CONFIG,
  subWallets: [],

  activeAutomations: {
    bumpBot: false,
    greenTwap: false,
    sniperGuard: true,
  },

  setConnectedWallet: (wallet) => {
    set({ connectedWallet: wallet });
    if (wallet) {
      get().refreshBalances();
    }
  },

  updateLaunchConfig: (partial) => {
    set((state) => ({
      activeLaunchConfig: { ...state.activeLaunchConfig, ...partial },
    }));
  },

  setSubWallets: (wallets) => set({ subWallets: wallets }),

  updateSubWallet: (id, partial) => {
    set((state) => ({
      subWallets: state.subWallets.map((w) => (w.id === id ? { ...w, ...partial } : w)),
    }));
  },

  setCurrentSlot: (slot) => set({ currentSlot: slot }),

  initSlotSubscription: () => {
    try {
      const subId = SolanaConnectionManager.subscribeSlot((slot) => {
        set({ currentSlot: slot });
      });
      set({ isSlotSubscribed: true });

      return () => {
        SolanaConnectionManager.unsubscribeSlot(subId).catch(console.error);
        set({ isSlotSubscribed: false });
      };
    } catch (err) {
      console.warn("WebSocket subscription fallback to polling:", err);
      const interval = setInterval(async () => {
        try {
          const connection = SolanaConnectionManager.getConnection();
          const slot = await connection.getSlot("confirmed");
          set({ currentSlot: slot });
        } catch {}
      }, 1000);

      return () => clearInterval(interval);
    }
  },

  toggleAutomation: (key, forceVal) => {
    set((state) => ({
      activeAutomations: {
        ...state.activeAutomations,
        [key]: forceVal !== undefined ? forceVal : !state.activeAutomations[key],
      },
    }));
  },

  addReclaimedRent: (sol) => {
    set((state) => ({
      reclaimedRentSol: Number((state.reclaimedRentSol + sol).toFixed(5)),
    }));
  },

  refreshBalances: async () => {
    const { connectedWallet, subWallets } = get();
    if (connectedWallet) {
      try {
        const bal = await SolanaConnectionManager.getSolBalance(connectedWallet);
        set({ walletBalanceSol: bal });
      } catch (err) {
        console.error("Error fetching master wallet balance:", err);
      }
    }

    if (subWallets.length > 0) {
      try {
        const updated = await Promise.all(
          subWallets.map(async (sw) => {
            const bal = await SolanaConnectionManager.getSolBalance(sw.publicKey);
            return { ...sw, balanceSol: bal };
          })
        );
        set({ subWallets: updated });
      } catch (err) {
        console.error("Error refreshing sub-wallet balances:", err);
      }
    }
  },
}));

