import { Figure } from "empryo";

export default function RealLogosCard() {
  const launchpads = [
    { name: "PumpFun", icon: "/icons/dex/pumpfun.webp" },
    { name: "Meteora DBC", icon: "/icons/dex/meteoradbc.webp" },
    { name: "Raydium LaunchLab", icon: "/icons/dex/raydium.webp" },
