    { name: "LetsBonk", icon: "/icons/dex/bonkfun.webp" },
    { name: "Bags", icon: "/icons/dex/bags.webp" },
    { name: "Anoncoin", icon: "/icons/dex/anoncoin.webp" },
    { name: "Surge", icon: "/icons/dex/surge.webp" },
    { name: "Printr", icon: "/icons/dex/printr.webp" },
