    { name: "meme.fun", icon: "/icons/dex/memefun.webp" },
    { name: "Pangea", icon: "/icons/dex/pangea.webp" }
  ];

  return (
    <Figure
      title="Real Official Logos Integrated (1:1 Proxima Layout)"
      subtitle="Replaced mock vector shapes with actual webp icons extracted from Proxima"
      caption="Live on http://localhost:3000/launch · Commit 92aa35d"
    >
