import { Figure } from "empryo";

export default function SolanaFirstCard() {
  const chains = [
    { name: "Solana", status: "12 LAUNCHPADS", state: "ACTIVE", style: "border-[#31E3AC] text-[#31E3AC] bg-[#102422]" },
    { name: "Robinhood", status: "COMING SOON", state: "DISABLED", style: "opacity-40 grayscale" },
    { name: "BNB Smart Chain", status: "COMING SOON", state: "DISABLED", style: "opacity-40 grayscale" },
    { name: "Arc", status: "COMING SOON", state: "DISABLED", style: "opacity-40 grayscale" },
    { name: "Ethereum", status: "COMING SOON", state: "DISABLED", style: "opacity-40 grayscale" },
    { name: "Base", status: "COMING SOON", state: "DISABLED", style: "opacity-40 grayscale" },
    { name: "X Layer", status: "COMING SOON", state: "DISABLED", style: "opacity-40 grayscale" }
  ];

  return (
    <Figure
      title="Solana-First Launch Focus Active"
      subtitle="Solana is the sole selectable deployment chain; all secondary networks darkened with 'COMING SOON'"
      caption="Live on http://localhost:3000/launch · Commit eb78266"
    >
      <div className="space-y-3 text-xs">
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          {chains.map((c, i) => (
            <div key={i} className={`p-2.5 rounded-lg border border-[#1C202B] bg-[#111218] ${c.style}`}>
              <div className="flex justify-between items-center mb-1">
                <span className="font-semibold text-[#F8FAFC]">{c.name}</span>
                <span className="text-[8px] font-bold px-1 py-0.2 rounded bg-black/40">{c.state}</span>
              </div>
              <div className="text-[10px] font-mono">{c.status}</div>
            </div>
          ))}
        </div>
      </div>
    </Figure>
  );
}

