  // PumpFun Specific Options (Screenshot 2)
  const [pumpOtcDesks, setPumpOtcDesks] = useState(false);
  const [pumpUsePaid, setPumpUsePaid] = useState(false);
  const [pumpZaio, setPumpZaio] = useState(false);
