export default function RenderDeployCard() {
  const steps = [
    { num: "1", title: "Select Service Type", desc: "Click '+ New' in Render and choose 'Web Service' (never Static Site, as SCRAMJET runs a live Node.js server for Helius WebSockets & Jito)." },
    { num: "2", title: "Connect GitHub", desc: "Select your repo: '0xfuckian/scramjet'. Render will auto-detect the 'render.yaml' blueprint we just pushed." },
    { num: "3", title: "Build & Start Commands", desc: "Build Command: 'npm ci && npm run build' · Start Command: 'npm run start' · Port: 3000." },
    { num: "4", title: "Credentials are Ready", desc: "Your Helius RPC, Turnkey credentials, and fee vault are already embedded as defaults in the codebase." }
  ];

  return (
    <Figure
      title="Render.com 1-Click Deployment Blueprint"
      subtitle="Production configuration pushed to GitHub in commit 8e83007"
      caption="Ready to launch on Render Web Service"
    >
      <div className="space-y-2 text-xs">
        {steps.map((s, idx) => (
          <div key={idx} className="p-2.5 rounded-lg border border-[#1C202B] bg-[#0E0F14] flex items-start gap-3">
            <span className="w-5 h-5 rounded-full bg-[#FF3E00]/20 text-[#FF3E00] flex items-center justify-center font-bold font-mono text-[11px] flex-shrink-0 mt-0.5">
              {s.num}
            </span>
            <div>
              <div className="font-semibold text-[#F8FAFC]">{s.title}</div>
              <div className="text-[11px] text-[#8E9AA8] leading-tight mt-0.5">{s.desc}</div>
            </div>
          </div>
        ))}
      </div>
    </Figure>
  );
}

