 73  export const BASE_LAUNCH_FEE_SOL = 0.15;
 74  export const PER_WALLET_EXECUTION_FEE_SOL = 0.005;
 75  
 76  export interface UpfrontLaunchFee {
 77    baseFeeSol: number;
 78    walletExecutionFeeSol: number;
