 86   * Base launch fee (0.15 SOL) + per-wallet coordination fee (0.005 SOL per wallet).
 87   * Even if launching with 0 dev buy and 0 sub-wallets, the base fee applies.
 88   */
 89  export function calculateUpfrontLaunchFee(walletCount: number = 0): UpfrontLaunchFee {
 90    const count = Math.max(0, walletCount);
 91    const walletFee = count * PER_WALLET_EXECUTION_FEE_SOL;
 92    const total = Number((BASE_LAUNCH_FEE_SOL + walletFee).toFixed(4));
 93    const lamports = BigInt(Math.floor(total * LAMPORTS_PER_SOL));
 94  
 95    return {
 96      baseFeeSol: BASE_LAUNCH_FEE_SOL,
 97      walletExecutionFeeSol: Number(walletFee.toFixed(4)),
 98      totalLaunchFeeSol: total,
 99      totalLaunchFeeLamports: lamports,
