  ...current,
  description: "Hypersonic Solana launchpad controller, Block-0 MEV engine, and fee audit deck.",
  surface: {
    ...current.surface,
    body: "Block-0 MEV bundles, live Jito tip floor, 350 bps fee routing audit, and devnet simulation.",
    blocks: current.surface.blocks.map(b => {
      if (b.kind === "stats") {
        return {
          ...b,
          items: [
            { ...b.items[0], hint: "Coinbase spot" },
            { ...b.items[1], hint: "Block-0 tip floor" },
            { ...b.items[2], hint: "350 bps vs 500 bps" },
            { ...b.items[3], hint: "Sub-wallet minimum" }
          ]
        };
      }
      if (b.kind === "kv") {
        return {
          ...b,
          rows: [
            { ...b.rows[0], v: "3.5% (350 bps) — 30% savings vs Proxima" },
            { ...b.rows[1], v: "5.0% (500 bps) competitor benchmark" },
            { ...b.rows[2], v: "0.01 SOL threshold (10x lower)" },
            { ...b.rows[3], v: "Recovers ~0.00204 SOL/wallet post-sale" },
            { ...b.rows[4], v: "Jito Block-0 atomic tip targeting" }
          ]
        };
      }
      if (b.kind === "select") {
        return {
          ...b,
          options: [
            { label: "Pump.fun (Bonding Curve)", prompt: "Configure Pump.fun launch parameters with 350 bps platform fee split." },
            { label: "Meteora DBC (Dynamic Curve)", prompt: "Configure Meteora Dynamic Bonding Curve with DLMM auto-reinvest." },
