          ]
        };
      }
      if (b.kind === "buttons") {
        return {
          ...b,
          items: [
            { ...b.items[0], prompt: "Run devnet simulation suite in scripts/devnet_test.ts and verify all 7 subsystems." },
            { ...b.items[1], prompt: "Verify 350 bps fee router and platform vault in src/lib/feeRouter.ts." },
            { ...b.items[2], prompt: "Test Jito Block Engine endpoints and tip accounts in src/lib/jito/." }
