 396  function distributeBuyAmounts(wallets: SubWallet[], config: MultiWalletTradeConfig): number[] {
 397    const base = wallets.map((wallet) => wallet.allocatedBuySol);
 398    if (config.amountDistribution === "EQUAL") {
 399      const average = base.reduce((sum, amount) => sum + amount, 0) / wallets.length;
 400      return wallets.map(() => average);
 401    }
 402    if (config.amountDistribution === "RANDOM_DEVIATION") {
 403      return base.map((amount) => Number((amount * (0.85 + Math.random() * 0.3)).toFixed(4)));
 404    }
