 406    const balanceTotal = wallets.reduce((sum, wallet) => sum + wallet.balanceSol, 0);
 407    const allocatedTotal = base.reduce((sum, amount) => sum + amount, 0);
 408    if (balanceTotal <= 0) return base;
 409    return wallets.map((wallet) =>
