 500      })
 501    );
 502    const confirmation = await monitorTransactionConfirmation(signature);
 503    if (!confirmation.confirmed) {
 504      throw new Error(confirmation.err ?? `Transaction ${signature} was not confirmed`);
 505    }
 506    return signature;
 507  }

