 375  function selectTradeWallets(wallets: SubWallet[], config: MultiWalletTradeConfig): SubWallet[] {
 376    if (wallets.length === 0 || config.dispersionPercent <= 0) return [];
 377  
 378    const fraction = Math.min(100, config.dispersionPercent) / 100;
 379    const take =
 380      config.selectionStrategy === "ALL"
 381        ? wallets.length
 382        : Math.min(wallets.length, Math.max(1, Math.ceil(wallets.length * fraction)));
 383  
 384    const ordered = [...wallets];
 385    if (config.selectionStrategy === "RANDOM") {
 386      ordered.sort(() => Math.random() - 0.5);
 387    } else if (config.selectionStrategy === "LOW_TOKENS") {
 388      ordered.sort((a, b) => a.tokenBalance - b.tokenBalance);
 389    } else if (config.selectionStrategy === "HIGH_TOKENS") {
 390      ordered.sort((a, b) => b.tokenBalance - a.tokenBalance);
 391    }
 392  
 393    return ordered.slice(0, take);
 394  }

