      bumpIntervalSeconds: 15,
      bumpMinSol: 0.05,
      bumpMaxSol: 0.15,
      enableGreenCandleTwap: true,
      twapMaxSellPercentPerSlice: 10,
      targetTrendingBoard: "PHOTON",
    },
    availableWallets: subWallets,
    sessionDurationMinutes: 2,
  });
