  console.log(`[7] Sniper Guard Defense Engine:`);
  const defenseResult = SniperGuardEngine.evaluateDefense({
    config: {
      enabled: true,
      triggerExternalBuySol: 5.0,
      action: "NUKE",
      nukeScope: "HOLDERS_ONLY",
    },
    externalBuyVolumeSol: 6.2, // Triggered!
    subWallets,
    devWallet: subWallets[0],
  });
