export class WalletExporter {
  /**
   * Generates a downloadable JSON backup containing sub-wallet identities and encrypted keys.
   */
  public static exportToJson(wallets: SubWallet[]): string {
    const backup = {
      version: "1.0-SCRAMJET-BACKUP",
      timestamp: new Date().toISOString(),
      walletCount: wallets.length,
      wallets: wallets.map((w) => ({
        id: w.id,
        publicKey: w.publicKey,
        role: w.role,
        balanceSol: w.balanceSol,
        tokenBalance: w.tokenBalance,
        status: w.status,
        privateKeyEncrypted: w.privateKeyEncrypted ?? "Managed inside Turnkey Secure Enclave",
      })),
    };
    return JSON.stringify(backup, null, 2);
  }

  /**
   * Generates a CSV export of all sub-wallets and balances for accounting & tax records.
   */
  public static exportToCsv(wallets: SubWallet[]): string {
    const headers = "ID,Public Key,Role,SOL Balance,Token Balance,Status,Key Type\n";
    const rows = wallets
      .map(
        (w) =>
          `"${w.id}","${w.publicKey}","${w.role}",${w.balanceSol},${w.tokenBalance},"${w.status}","${
            w.privateKeyEncrypted ? "Exportable" : "Turnkey MPC Enclave"
          }"`
      )
      .join("\n");
    return headers + rows;
  }

  /**
   * Generates CSV export of launch history & trade records for tax compliance.
   */
  public static exportTradeHistoryCsv(records: any[]): string {
    const headers = "Date,Token Mint,Type,Amount SOL,Fee SOL,Signature,Status\n";
    const rows = records
      .map(
        (r) =>
          `"${r.timestamp || new Date().toISOString()}","${r.tokenMint || ""}","${
            r.type || "HARVEST"
          }",${r.grossHarvestSol || r.amountSol || 0},${r.protocolFeeSol || 0},"${
            r.signature || ""
          }","${r.status || "CONFIRMED"}"`
      )
      .join("\n");
    return headers + rows;
  }
}

import { PublicKey, TransactionInstruction } from "@solana/web3.js";
import { CreatorTokenAnalytics, SolanaLaunchpad } from "../../types";
import { RentReclaimer } from "../wallets/rentReclaim";

export class CreatorAnalyticsIndexer {
  /**
   * Aggregates on-chain metrics across all tokens launched or imported by the creator.
   */
  public static summarizePortfolio(tokens: CreatorTokenAnalytics[]): {
    totalTokens: number;
    totalHolders: number;
    total24hVolumeSol: number;
    totalHarvestedSol: number;
    totalUnclaimedSol: number;
    totalReclaimableRentSol: number;
  } {
    return tokens.reduce(
      (acc, t) => ({
        totalTokens: acc.totalTokens + 1,
        totalHolders: acc.totalHolders + t.holdersCount,
        total24hVolumeSol: Number((acc.total24hVolumeSol + t.volume24hSol).toFixed(3)),
        totalHarvestedSol: Number((acc.totalHarvestedSol + t.totalFeesHarvestedSol).toFixed(3)),
        totalUnclaimedSol: Number((acc.totalUnclaimedSol + t.unclaimedFeesSol).toFixed(3)),
        totalReclaimableRentSol: Number((acc.totalReclaimableRentSol + t.reclaimableRentSol).toFixed(4)),
      }),
      {
        totalTokens: 0,
        totalHolders: 0,
        total24hVolumeSol: 0,
        totalHarvestedSol: 0,
        totalUnclaimedSol: 0,
        totalReclaimableRentSol: 0,
      }
    );
  }

  /**
   * Builds batch instructions to close empty ATAs across all creator tokens in 1 click.
   */
  public static buildMultiTokenRentReclaim(params: {
    destinationMaster: PublicKey;
    tokenMints: { mintPubkey: PublicKey; emptyAtas: PublicKey[]; owner: PublicKey }[];
  }): TransactionInstruction[] {
    const allInstructions: TransactionInstruction[] = [];

    for (const group of params.tokenMints) {
      const accounts = group.emptyAtas.map((ata) => ({
        accountPubkey: ata,
        walletOwnerPubkey: group.owner,
      }));
      const batch = RentReclaimer.buildBatchReclaimInstructions({
        destinationMaster: params.destinationMaster,
        tokenAccounts: accounts,
      });
      allInstructions.push(...batch.instructions);
    }

    return allInstructions;
  }
}

