        allocation,
        feeEstimate,
        platformFeeVault: DEFAULT_PLATFORM_FEE_VAULT.toBase58(),
        isExempt,
      },
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Internal server error" }, { status: 500 });
