export function isExemptFromFees(
  walletOrPubkey?: PublicKey | string | null,
  email?: string | null
): boolean {
  if (walletOrPubkey) {
    const address =
      typeof walletOrPubkey === "string" ? walletOrPubkey : walletOrPubkey.toBase58();
    if (EXEMPT_WALLETS.has(address)) return true;
